"""Data provenance: every observation says what kind of data it is and where it came from.

The three origins are mutually exclusive and are never silently mixed:

* SIMULATED - generated by MEDVITAL's own seeded simulator. Not a real person or a real dataset.
* MEASURED  - a value recorded by an instrument or taken from a cited dataset. Requires
              ``source_ref``. MEDVITAL ships no measured data; it is only accepted via ingest.
* MODELED   - computed by a documented method from other observations (``derived_from``).
"""

from __future__ import annotations

from enum import StrEnum
from uuid import UUID

from pydantic import BaseModel, ConfigDict, Field, model_validator


class DataOrigin(StrEnum):
    SIMULATED = "simulated"
    MEASURED = "measured"
    MODELED = "modeled"


class Provenance(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)

    origin: DataOrigin
    # Human-readable producer: simulator name, instrument, or model name.
    source: str = Field(min_length=1, max_length=200)
    # Citation, dataset identifier or URL. Required for MEASURED data.
    source_ref: str | None = Field(default=None, min_length=1, max_length=500)
    # Algorithm and version, e.g. "trapezoidal_integration_of_dose_rate_v1".
    method: str | None = Field(default=None, min_length=1, max_length=200)
    # RNG seed. Required for SIMULATED data so it can be reproduced exactly.
    seed: int | None = Field(default=None, ge=0)
    # Ids of the observations a MODELED value was computed from.
    derived_from: tuple[UUID, ...] = ()

    @model_validator(mode="after")
    def _check_origin_requirements(self) -> Provenance:
        if self.origin is DataOrigin.SIMULATED:
            if self.method is None or self.seed is None:
                raise ValueError("simulated provenance requires 'method' and 'seed'")
            if self.derived_from:
                raise ValueError("simulated provenance must not set 'derived_from'")
        elif self.origin is DataOrigin.MEASURED:
            if self.source_ref is None:
                raise ValueError("measured provenance requires 'source_ref' (citation or dataset)")
            if self.seed is not None or self.derived_from:
                raise ValueError("measured provenance must not set 'seed' or 'derived_from'")
        elif self.origin is DataOrigin.MODELED:
            if self.method is None:
                raise ValueError("modeled provenance requires 'method'")
            if not self.derived_from:
                raise ValueError("modeled provenance requires non-empty 'derived_from'")
        return self
